import java.util.Scanner;

public class CF552C_Variant3 {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int baseW = input.nextInt();
        int num = input.nextInt();
        input.close();

        int[] digitsArray = new int[100];
        int position = 0;

        while (num > 0) {
            digitsArray[position] = num % baseW;
            num /= baseW;
            position++;
        }

        for (int i = 0; i < digitsArray.length; i++) {
            if (digitsArray[i] == 0 || digitsArray[i] == 1 || digitsArray[i] == -1) {
                continue;
            } else if (digitsArray[i] == baseW - 1) {
                digitsArray[i] -= baseW;
                digitsArray[i + 1] += 1;
            } else if (digitsArray[i] == baseW) {
                digitsArray[i] = 0;
                digitsArray[i + 1] += 1;
            } else {
                System.out.println("NO");
                return;
            }
        }
        System.out.println("YES");
    }
}
